mapper.select:
select d.id, d.sku_id as skuId, d.bundle_id as bundleId, d.title, d.target_type as targetType, d.total_stock as totalStock, d.max_participants as maxParticipants, d.winner_count as winnerCount, d.price, d.start_time as startTime, d.end_time as endTime, d.draw_time as drawTime, d.status, d.description, case when d.target_type = 1 then spu.name when d.target_type = 2 then b.name else null end as targetName, case when d.target_type = 1 then sk.color_name else null end as skuColorName, count(dr.id) as participantCount from draw d left join shoe_sku sk on sk.id = d.sku_id left join shoe_spu spu on spu.id = sk.spu_id left join bundle b on b.id = d.bundle_id left join draw_record dr on dr.draw_id = d.id
and d.title like concat('%',#{title},'%')
and d.status = #{status}
and d.target_type = #{targetType}
group by d.id, d.sku_id, d.bundle_id, d.title, d.target_type, d.total_stock, d.max_participants, d.winner_count, d.price, d.start_time, d.end_time, d.draw_time, d.status, d.description, spu.name, sk.color_name, b.name order by d.update_time desc, d.id desc
